css:
.wrapper {
  --c1: #ff4d6d;
  --c2: #ff9e2c;
  --c3: #ffe74c;
  --c4: #5cff9d;
  --c5: #4dd2ff;
  --c6: #b58cff;

  --spectrum: linear-gradient(
    90deg,
    var(--c1),
    var(--c2),
    var(--c3),
    var(--c4),
    var(--c5),
    var(--c6),
    var(--c1)
  );

  --light-1: #ff4d6d55;
  --light-2: #4dd2ff55;

  --duration: 3s;
  --flow: 6s;
  --transition: 0.5s;

  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  width: max-content;
  height: max-content;
}

.light-1,
.light-2 {
  display: none;
}

.ai-bg {
  position: absolute;
  z-index: -1;
  fill: none;
  transition: filter var(--transition) ease;
}

.line-bg {
  stroke: #fff1;
  stroke-width: 0.5;
}

.line {
  stroke: none;
  stroke-width: 0;
  stroke-dasharray: 16 56;
  transition: stroke var(--transition) ease-in-out;
}

.dot {
  fill: #555;
  opacity: 0.3;
  transition: fill var(--transition) ease;
}

.line:nth-child(6n + 1),
.dot:nth-child(6n + 1) {
  --c: var(--c1);
}
.line:nth-child(6n + 2),
.dot:nth-child(6n + 2) {
  --c: var(--c2);
}
.line:nth-child(6n + 3),
.dot:nth-child(6n + 3) {
  --c: var(--c3);
}
.line:nth-child(6n + 4),
.dot:nth-child(6n + 4) {
  --c: var(--c4);
}
.line:nth-child(6n + 5),
.dot:nth-child(6n + 5) {
  --c: var(--c5);
}
.line:nth-child(6n),
.dot:nth-child(6n) {
  --c: var(--c6);
}

.ai-btn {
  position: relative;
  width: max-content;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 120px;
  min-height: 48px;
  border-radius: 7px;
  background-color: #000;
  background-image: url(data:image/png;base64,),
    linear-gradient(to bottom, #fff1, transparent);
  color: #ddd;
  border: 1px solid #2a2a2e;
  font-size: 16px;
  font-weight: 500;
  font-family: "Inter", sans-serif;
  letter-spacing: -0.5px;
  cursor: pointer;
  transition: all var(--transition) ease;
  box-shadow:
    0 0 30px -12px var(--light-1),
    inset -1px -1px 1px 1px #000,
    inset -2px -2px 2px 1px #fff2,
    inset 1px 1px 1px 1px #000,
    inset 2px 2px 2px 1px #fff2;
}

.ai-btn::before {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: 8px;
  padding: 1px;
  background: var(--spectrum);
  background-size: 300% 100%;
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask-composite: exclude;
  opacity: 0.3;
  filter: saturate(0.7);
  animation: flow var(--flow) linear infinite;
  transition:
    opacity var(--transition) ease,
    filter var(--transition) ease;
  pointer-events: none;
}

.ai-btn .txt-1,
.ai-btn .txt-2 {
  position: absolute;
  background: var(--spectrum);
  background-size: 300% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: flow var(--flow) linear infinite;
  filter: saturate(0.35) brightness(1.1);
  transition:
    opacity 0.4s ease,
    filter var(--transition) ease;
}
.ai-btn .txt-1 {
  opacity: 1;
}
.ai-btn .txt-2 {
  opacity: 0;
}

.ai-btn:hover {
  border-color: #3a3a40;
  box-shadow:
    0 0 34px -10px var(--light-2),
    0 0 22px -14px var(--light-1),
    inset -1px -1px 1px 1px #000,
    inset -2px -2px 2px 1px #fff2,
    inset 1px 1px 1px 1px #000,
    inset 2px 2px 2px 1px #fff2;
}
.ai-btn:hover::before {
  opacity: 0.9;
  filter: saturate(1.2);
}
.ai-btn:hover .txt-1,
.ai-btn:hover .txt-2 {
  filter: saturate(1) brightness(1.35) drop-shadow(0 0 8px #ffffff40);
}
.wrapper:has(.ai-btn:hover) .dot {
  fill: var(--c);
  opacity: 0.8;
}

.ai-btn:active {
  box-shadow:
    0 0 10px var(--light-1),
    inset -1px -1px 1px 1px #000,
    inset -2px -2px 2px 1px #fff2,
    inset 1px 1px 1px 1px #000,
    inset 2px 2px 2px 1px #fff2;
}

.ai-btn:focus {
  background-color: #131317;
  border-color: transparent;
  outline: none;
  animation: pulse var(--duration) ease-in-out infinite;
}
.ai-btn:focus::before {
  opacity: 1;
  filter: saturate(1.4);
  animation-duration: calc(var(--flow) * 0.4);
}

.ai-btn:focus .txt-1 {
  opacity: 0;
}
.ai-btn:focus .txt-2 {
  opacity: 1;
  filter: saturate(1.2) brightness(1.3);
  animation:
    flow calc(var(--flow) * 0.4) linear infinite,
    pulse-text var(--duration) ease-in-out infinite;
}
.wrapper:has(.ai-btn:focus) .dot {
  fill: var(--c);
  animation: dot-opac calc(var(--duration) * 0.5) linear infinite;
}
.wrapper:has(.ai-btn:focus) .dot:nth-child(odd) {
  animation-delay: calc(var(--duration) * 0.1);
}
.wrapper:has(.ai-btn:focus) .line {
  stroke: var(--c);
  animation: dash var(--duration) ease-out infinite;
}
.wrapper:has(.ai-btn:focus) .line:nth-child(odd) {
  animation-delay: calc(var(--duration) * 0.1);
}
.wrapper:has(.ai-btn:focus) .line:nth-child(3n) {
  animation-delay: calc(var(--duration) * 0.25);
}

.wrapper:has(.ai-btn:focus) .ai-bg {
  animation: hue calc(var(--flow) * 2) linear infinite;
}

@keyframes flow {
  to {
    background-position: 300% 50%;
  }
}

@keyframes hue {
  from {
    filter: drop-shadow(0 0 4px #ffffff30) hue-rotate(0deg);
  }
  to {
    filter: drop-shadow(0 0 4px #ffffff30) hue-rotate(360deg);
  }
}

@keyframes pulse-text {
  0%,
  100% {
    text-shadow: 0 0 2px #0000;
  }
  50% {
    text-shadow: 0 0 24px #ffffff55;
  }
}

@keyframes dot-opac {
  0%,
  100% {
    opacity: 0.15;
  }
  20% {
    opacity: 1;
  }
}

@keyframes pulse {
  0%,
  100% {
    box-shadow:
      0 0 20px var(--light-2),
      inset -1px -1px 1px 1px #000,
      inset -2px -2px 2px 1px #fff2,
      inset 1px 1px 1px 1px #000,
      inset 2px 2px 2px 1px #fff2;
  }
  50% {
    box-shadow:
      0 0 60px 0px var(--light-1),
      inset -1px -1px 1px 1px #000,
      inset -2px -2px 2px 1px #fff2,
      inset 1px 1px 1px 1px #000,
      inset 2px 2px 2px 1px #fff2;
  }
}

@keyframes dash {
  0% {
    stroke-width: 0;
    stroke-dashoffset: 10;
    opacity: 0.35;
  }
  50% {
    stroke-width: 0.6;
    stroke-dashoffset: 88;
    opacity: 1;
  }
  100% {
    stroke-width: 0;
    stroke-dashoffset: 166;
    opacity: 0.35;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ai-btn::before,
  .ai-btn .txt-1,
  .ai-btn .txt-2,
  .wrapper:has(.ai-btn:focus) .line,
  .wrapper:has(.ai-btn:focus) .dot,
  .wrapper:has(.ai-btn:focus) .ai-bg,
  .ai-btn:focus {
    animation: none;
  }
  .wrapper:has(.ai-btn:focus) .line {
    stroke-width: 0.5;
    opacity: 0.8;
  }
}
